    written: [
      { q: "अनुपम मिश्र कौन थे?", a: "अनुपम मिश्र प्रखर **लेखक, संपादक और पर्यावरणविद्** थे; उनकी प्रसिद्ध पुस्तक 'आज भी खरे हैं तालाब' है।", marks: 1 },
      { q: "जल-चक्र किसे कहते हैं?", a: "समुद्र से भाप उठकर बादल बनने, वर्षा होने और नदियों के रास्ते पानी के फिर समुद्र में मिलने के क्रम को **जल-चक्र** कहते हैं।", marks: 1 },
      { q: "गर्मियों में नलों के संबंध में पाठ में क्या समस्याएँ बताई गई हैं?", a: "1. नलों में पूरे समय पानी नहीं आता और बेवक्त आता है।\n2. इससे लोग रात-सबेरे बर्तन भरते हैं और आपस में झगड़े होते हैं।", marks: 2 },
      { q: "लेखक ने तालाबों और झीलों को गुल्लक भरने वाला क्यों कहा है?", a: "1. तालाब और झीलें वर्षा का जल अपने में जमा करते हैं।\n2. वह जल रिसकर भूजल में मिलता है, जिसे साल भर निकालकर उपयोग किया जा सकता है।", marks: 2 },
      { q: "बाढ़ से कौन-कौन-से नुकसान होते हैं? पाठ के आधार पर दो लिखिए।", a: "1. घर, स्कूल, सड़कें और रेल की पटरियाँ पानी में डूब जाती हैं।\n2. देश के कई भाग डूब जाते हैं और कुछ दिनों के लिए सब कुछ थम जाता है।", marks: 2 },
      { q: "पाठ के अनुसार अकाल और बाढ़ से बचने के उपाय तीन बिंदुओं में लिखिए।", a: "1. जल-चक्र को ठीक से समझना।\n2. वर्षा के जल को रोककर जमा करना और भूजल भंडार सुरक्षित रखना।\n3. तालाबों, झीलों और नदियों की अच्छी तरह रखवाली करना।", marks: 3 },
      { q: "लोगों ने तालाब क्यों पाट दिए और उसका क्या परिणाम हुआ?", a: "1. ज़मीन के लालच में तालाब कचरे से पाटकर उन पर मकान, बाज़ार, स्टेडियम आदि बना दिए गए।\n2. इससे भूजल भंडार नहीं भर पाया।\n3. परिणामस्वरूप गर्मी में नल सूखते हैं और वर्षा में बस्तियाँ डूबती हैं।", marks: 3 },
      { q: "पढ़िए और उत्तर दीजिए – एक गाँव में पुराने तालाब को सब ने मिलकर साफ़ किया और वर्षा से पहले उसकी मेड़ें मज़बूत कीं। अगली वर्षा में तालाब भर गया, कुओं का जलस्तर बढ़ गया और खेतों में पानी की कमी नहीं हुई।\n(i) गाँव वालों ने किस पाठ-विचार को अपनाया?\n(ii) तालाब भरने से कुओं का जलस्तर क्यों बढ़ा?\n(iii) आप पानी की बचत के लिए घर में क्या करेंगे?", a: "(i) उन्होंने **जलस्रोतों की रखवाली और वर्षा-जल रोकने** का विचार अपनाया।\n(ii) तालाब का पानी रिसकर भूजल में मिलता है, जिससे कुओं का जलस्तर बढ़ता है।\n(iii) जैसे – नल खुला न छोड़ना, पानी की बर्बादी रोकना और बचा पानी पौधों में डालना।", marks: 4, type: "case" }
    ]
